using NUnit.Framework;

[TestFixture]
public class BinarySearchTargetTests
{
    [Test]
    public void Finds_When_Present()
    {
        Assert.That(new Solution().BinarySearchTarget(new[] { 1, 3, 5, 7 }, 5), Is.True);
    }

    [Test]
    public void Not_Found_When_Missing()
    {
        Assert.That(new Solution().BinarySearchTarget(new[] { 1, 3, 5, 7 }, 2), Is.False);
    }

    [Test]
    public void Empty_Returns_False()
    {
        Assert.That(new Solution().BinarySearchTarget(System.Array.Empty<int>(), 1), Is.False);
    }

    [Test]
    public void Single_Match()
    {
        Assert.That(new Solution().BinarySearchTarget(new[] { 42 }, 42), Is.True);
    }

    [Test]
    public void Single_NoMatch()
    {
        Assert.That(new Solution().BinarySearchTarget(new[] { 42 }, 7), Is.False);
    }
}
